def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            value = f"{local}@{domain}"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""
        return value

    def normalize_phone(value):
        value = re.split(r"ext\.?|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        if "T" in value:
            return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S")
        if "/" in value:
            return datetime.strptime(value, "%m/%d/%Y")
        return datetime.strptime(value, "%Y-%m-%d")

    def opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        prepared.append({
            "index": index,
            "row": row,
            "email": email,
            "phone": phone,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "zip": normalize_zip(row["zip"]),
            "updated": parse_updated(row["updated"]),
        })

    # Connected components make matching transitive.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_last_owner = {}

    for i, item in enumerate(prepared):
        if item["email"]:
            if item["email"] in email_owner:
                union(i, email_owner[item["email"]])
            else:
                email_owner[item["email"]] = i

        if item["phone"] and item["last_name"]:
            key = (item["phone"], item["last_name"].lower())
            if key in phone_last_owner:
                union(i, phone_last_owner[key])
            else:
                phone_last_owner[key] = i

    groups = {}
    for i, item in enumerate(prepared):
        groups.setdefault(find(i), []).append(item)

    def pick(group, field, valid_only=False):
        candidates = []
        for item in group:
            value = item[field]
            if valid_only:
                if not value:
                    continue
            elif not value:
                continue

            source = item["row"]["source"].strip().lower()
            candidates.append((
                source == "manual",
                item["updated"],
                -item["index"],
                value,
            ))
        return max(candidates)[3] if candidates else ""

    output = []
    for group in sorted(groups.values(), key=lambda g: min(x["index"] for x in g)):
        tags = set()
        for item in group:
            tags.update(
                tag.strip().lower()
                for tag in re.split(r"[;,]", item["row"]["tags"])
                if tag.strip()
            )

        source_value = pick(
            [
                {**item, "source_value": item["row"]["source"].strip().lower()}
                for item in group
            ],
            "source_value",
        )

        output.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email", valid_only=True),
            "phone": pick(group, "phone", valid_only=True),
            "source": source_value,
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(opted_out(x["row"]["opted_out"]) for x in group) else "N",
            "updated": max(x["updated"] for x in group).strftime("%Y-%m-%d"),
        })

    return output
